<?php

namespace App\Support;

use App\Models\SiteContent;
use Illuminate\Database\QueryException;
use Illuminate\Support\Facades\File;
use RuntimeException;

/**
 * Site data for the public website: the JSON generated by SchoolForge
 * (resources/school/site.json) with content edited in the admin panel applied on top.
 */
class SchoolSite
{
    /**
     * @var array{school: array<string, mixed>, content: array<string, mixed>, theme: array<string, mixed>, navigation: list<array{label: string, href: string}>, layout: array<string, mixed>, pages: list<array{slug: string, title: string, description?: string, sections: list<array<string, mixed>>}>}|null
     */
    private ?array $data = null;

    public function __construct(private readonly string $path) {}

    /**
     * @return array{school: array<string, mixed>, content: array<string, mixed>, theme: array<string, mixed>, navigation: list<array{label: string, href: string}>, layout: array<string, mixed>, pages: list<array{slug: string, title: string, description?: string, sections: list<array<string, mixed>>}>}
     */
    public function data(): array
    {
        if ($this->data === null) {
            $site = $this->fileData();

            foreach ($this->overrides() as $key => $value) {
                if (ContentSchema::find($key) !== null) {
                    $site = ContentSchema::apply($site, $key, $value);
                }
            }

            $this->data = $this->withArticlePages($site);
        }

        return $this->data;
    }

    /**
     * The generated site data without admin edits.
     *
     * @return array<string, mixed>
     */
    public function fileData(): array
    {
        if (! File::exists($this->path)) {
            throw new RuntimeException("School site data not found at [{$this->path}]. Run `schoolforge sync` in the project root.");
        }

        return json_decode(File::get($this->path), true, flags: JSON_THROW_ON_ERROR);
    }

    /**
     * Forget cached data so the next read picks up new admin edits.
     */
    public function refresh(): void
    {
        $this->data = null;
    }

    /**
     * @return array{slug: string, title: string, description?: string, sections: list<array<string, mixed>>}|null
     */
    public function findPage(string $slug): ?array
    {
        foreach ($this->data()['pages'] as $page) {
            if ($page['slug'] === $slug) {
                return $page;
            }
        }

        return null;
    }

    public function schoolName(): string
    {
        return (string) $this->data()['school']['name'];
    }

    /**
     * @return list<string>
     */
    public function fontStylesheets(): array
    {
        return $this->data()['theme']['fontImports'] ?? [];
    }

    /**
     * @return array<string, mixed>
     */
    private function overrides(): array
    {
        try {
            return SiteContent::query()->pluck('value', 'key')->all();
        } catch (QueryException) {
            return [];
        }
    }

    /**
     * Rebuilds the per-article news pages so stories added in the admin panel get their own URL.
     *
     * @param  array<string, mixed>  $site
     * @return array<string, mixed>
     */
    private function withArticlePages(array $site): array
    {
        $pages = array_values(array_filter(
            $site['pages'],
            fn (array $page): bool => ! collect($page['sections'])->contains('type', 'article'),
        ));
        $slugs = array_column($pages, 'slug');

        foreach ($site['content']['news'] ?? [] as $article) {
            $slug = '/news/'.$article['slug'];

            if (! empty($article['body']) && ! in_array($slug, $slugs, true)) {
                $pages[] = array_filter([
                    'slug' => $slug,
                    'title' => $article['title'],
                    'description' => $article['excerpt'] ?? null,
                    'showInNav' => false,
                    'sections' => [['type' => 'article', 'newsSlug' => $article['slug']]],
                ], fn ($value): bool => $value !== null);
                $slugs[] = $slug;
            }
        }

        $site['pages'] = $pages;

        return $site;
    }
}
